CREATE SEQUENCE evt.state_changes_id_seq;
ALTER SEQUENCE evt.state_changes_id_seq OWNED BY evt.state_changes.id;
ALTER TABLE evt.state_changes ALTER COLUMN id SET DEFAULT nextval('evt.state_changes_id_seq');
ALTER TABLE evt.state_changes ADD CONSTRAINT required_serial_id CHECK(id IS NOT NULL) NOT VALID;
SELECT setval('evt.state_changes_id_seq',greatest(coalesce((SELECT max(id) FROM evt.state_changes),0)+1,1),false);
